import json, sys
OUT = sys.argv[1]
F = []
def add(domain, title, component, evidence, status, conf, description, impact='', remediation='', repro='', sev='Info'):
    F.append(dict(id='PCL-%03d' % (len(F) + 1), domain=domain, title=title, severity=sev, component=component,
                  evidence=evidence, status=status, confidence=conf, impact=impact, remediation=remediation,
                  description=description, reproduction=repro))

R_DEX = "Static: DEX bytecode scan (scripts/pcl/dexcode.py -> pcl_out/code.db) + mini-disassembler scripts/pcl/dis.py on the APK's classesN.dex"
def R_JADX(cls, m): return "REA/JADX: rea.sh inspect-android-method <apk> %s %s (decompiled body saved under pcl_out/jadx/)" % (cls, m)

